-- =====================================================================
-- AnarBib — La preuve de l'aller-retour PMB, par la base (H27)
-- ENGENDRÉE par src/tests/pmb-aller-retour-base.test.js — ne pas modifier à la main :
--   REGENERER_H27=1 npx vitest run src/tests/pmb-aller-retour-base.test.js
--
-- Les 64 lignes de staging que la VRAIE edge function d'import écrit pour
-- les deux fixtures exportées par PMB 8.1 (tests/pmb/fixtures) sont promues ;
-- le lot est approuvé, publié, puis exporté par fn_export_catalog_lote.
--
-- T1 promotion : une notice par ligne, un brouillon d'exemplaire par exemplaire (46).
-- T2 publication du lot : toutes les notices, et EXACTEMENT les exemplaires du
--    fichier — les 22 notices qui n'en ont pas n'en reçoivent pas (IMP-25).
-- T3 l'export rend EXACTEMENT l'attendu figé (tests/pmb/aller-retour-attendu.json),
--    identifiants internes, tombos et id de la source mis à part.
-- T4 la réémission (IMP-22) : l'enregistrement d'origine revient tel quel, sans
--    ses zones d'exemplaire, pour la bibliothèque qui l'a importé.
-- T5 (H21 lot 2, juste après T1) la création est inchangée : les brouillons et
--    leurs responsabilités sont, champ par champ, ceux que la définition d'avant
--    le lot 2 créait (tests/pmb/aller-retour-brouillons.json), identifiants
--    internes et horodatages mis à part.
-- T6 (H21 lot 2) une seule règle : chaque brouillon est ce que
--    ingest.fn_import_row_as_book dit de sa ligne, et la création l'appelle.
-- T7 (H21 lot 2) la publication pose la base de chaque identifiant d'origine,
--    exacte (correspondance, enregistrement d'origine, ligne, run, confirmée).
-- T8 (H21 lot 2) l'export lu dans la base est identique à l'export par le
--    repli sur marc_json.ingest (le chemin d'avant), et lit bien la base.
--
-- Capture de l'attendu : avec anarbib.h27_capture = on, la suite émet l'export
-- projeté et les brouillons projetés en NOTICE (tests/pmb/capturer-attendu-h27.sh) ; avec
-- anarbib.h27_export = on, l'export complet et les autorités (le fichier du
-- réimport dans PMB : tests/pmb/banc/essai-reimport-pmb.sh).
-- Toutes les écritures sont annulées : la suite se termine par un RAISE.
--   Bilan OK : 'ALLER-RETOUR-PMB OK : N/N'
-- =====================================================================
DO $$
DECLARE
  v_passed int := 0; v_failed int := 0; v_failures text[] := ARRAY[]::text[]; v_t text;
  v_coord uuid := '11111111-1111-1111-1111-111111111111';  -- coordenador BLMF (seed)
  v_admin uuid := '22222222-2222-2222-2222-222222222222';  -- compte sans rôle (seed) -> admin réseau ici
  v_lib   uuid := '1234825f-a0f9-4fbd-a875-6551c30ea4ca';  -- BLMF de test (seed)
  v_src bigint; v_run bigint; v_lot bigint; v_res jsonb; v_exp jsonb; v_proj jsonb; v_ecarts text[];
  v_attendu jsonb := $j${"library":{"id":"1234825f-a0f9-4fbd-a875-6551c30ea4ca","name":"BLMF (base de test)","slug":"blmf-test","country":"Brasil","short_name":null,"default_locale":"pt-BR"},"records":[{"cdd":"840","isbn":"2-211-04459-X","work":{"title":"Bac en poche"},"year":"1997","items":[{"code":"33700004388761","callNumber":"JR SOU","visibility":"public","circulationPolicy":"ambos"}],"notes":"La terre est devenue plate comme on se l'imaginait au Moyen Age et il ne faut pas trop s'approcher du bord... -- Services Documentaires Multimédia, C'était, évidemment, une journée magnifique. Une journée pour le Catalogue de la Compagnie. A ce moment là, le bureau de Kin donnait sur un lagon frangé de palmiers. Des rouleaux se brisaient contre les récifs...\n\nAssuntos importados: Roman d'aventure","pages":166,"place":"Paris","title":"Bac en poche","source":{"leader":"01801nam0 22002651i 450 ","dialect":"unimarc","itemTag":"995","fieldsCount":18},"language":"fr","originId":"1","publisher":"L'École des loisirs","collection":"Médium","externalIds":[{"label":"PMB 8.1 (fixtures)","value":"1"}],"contributors":[{"name":"Souton, Dominique","role":"autor","nature":"person","primary":true,"roleCode":"070"}],"materialType":"livro","responsibility":"Souton, Dominique"},{"isbn":"2-02-029506-7","work":{"title":"Catfish blues"},"year":"1997","items":[{"code":"22020295067","callNumber":"JR HER","visibility":"public","circulationPolicy":"ambos"},{"code":"6438646236","callNumber":"R HER","visibility":"public","circulationPolicy":"ambos"}],"notes":"Bibliogr., discogr. des oeuvres de l'auteur, 2 p.\n\nCatfish Blues, 12 ans, n'a qu'une idée en tête: fuir la plantation de coton où travaillent ses frères et soeurs et suivre son oncle Eddie pour devenir chanteur de blues à Chicago. Chronique de la vie d'un petit Noir aux prises avec les escrocs de tout poil, y compris le Ku Klux Klan, ce roman vaut aussi par la vivacité de son écriture. Un beau portrait d'époque. --Laurence Liban, ©Lire\n\nPalavras-chave importadas: coton; blues; musique; racisme\n\nAssuntos importados: Littérature française","pages":154,"place":"Paris","title":"Catfish blues","source":{"leader":"02504nam0 22002771i 450 ","dialect":"unimarc","itemTag":"995","fieldsCount":17},"language":"fr","originId":"2","publisher":"Seuil","externalIds":[{"label":"PMB 8.1 (fixtures)","value":"2"}],"contributors":[{"name":"Herzhaft, Gérard","role":"autor","nature":"person","primary":true,"roleCode":"070"}],"materialType":"livro","responsibility":"Herzhaft, Gérard"},{"cdd":"800","isbn":"2-84146-554-3","work":{"title":"Trois fêlés et un pendu"},"year":"1998","items":[{"code":"33700003413727","callNumber":"ER OPP","visibility":"public","circulationPolicy":"ambos"}],"notes":"Lucien a trouvé un trésor dans une grange abandonnée. Lorsqu'il y retourne avec ses copains, un homme est pendu au centre du bâtiment. Subterfuge pour les faire fuir, le pendu n'est pas mort et le trésor est sien. Grâce à Dédé qui s'est sauvé chercher du secours, le criminel est écroué. -- Services Documentaires Multimédia\n\nPalavras-chave importadas: copains; policier\n\nAssuntos importados: Littérature française","pages":29,"place":"Paris","title":"Trois fêlés et un pendu","source":{"leader":"01863nam0 22002531i 450 ","dialect":"unimarc","itemTag":"995","fieldsCount":17},"language":"fr","originId":"3","publisher":"Syros jeunesse","externalIds":[{"label":"PMB 8.1 (fixtures)","value":"3"}],"contributors":[{"name":"Oppel, Jean-Hugues","role":"autor","nature":"person","primary":true,"roleCode":"070"}],"materialType":"livro","responsibility":"Oppel, Jean-Hugues"},{"cdd":"840","isbn":"2-86274-547-2","work":{"title":"Le dieu devenu homme"},"year":"1998","items":[{"code":"33700003470461","callNumber":"R ZIM","visibility":"public","circulationPolicy":"ambos"}],"notes":"Quatorze nouvelles dont l'intrigue, ayant un personnage célèbre comme actant, se déroule entre 1820 et 1867. On doit ajouter pour l'intérêt du lecteur que quelques-uns des personnages se nomment Hugo, Lamartine, Vigny, Musset, Balzac... -- Services Documentaires Multimédia\n\nRecueil de nouvelles\n\nPalavras-chave importadas: roman historique,fiction; nouvelle; nouvelles\n\nAssuntos importados: Nouvelles","pages":125,"place":"Paris","title":"Le dieu devenu homme","source":{"leader":"01869nam0 22002651i 450 ","dialect":"unimarc","itemTag":"995","fieldsCount":18},"language":"fr","originId":"4","publisher":"le Cherche-Midi éd.","externalIds":[{"label":"PMB 8.1 (fixtures)","value":"4"}],"contributors":[{"name":"Zimmermann, Daniel","role":"autor","nature":"person","primary":true,"roleCode":"070"}],"materialType":"livro","responsibility":"Zimmermann, Daniel"},{"cdd":"840","isbn":"2-84146-452-0","work":{"title":"Sarah de Cordoue"},"year":"1997","items":[{"code":"33700003719453","callNumber":"JR CAU","visibility":"public","circulationPolicy":"ambos"}],"notes":"A défaut de fils, un vieux savant mal en point fait de sa fille aînée son disciple. La grande bibliothèque de Cordoue est interdite aux femmes. Pour accomplir les voeux de son père Sarah accepte de se travestir, de devenir Samuel. Elle reçoit un poème galant d'un jeune étudiant musulman. Qui, de Samuel ou de Sarah aime-t-il? Une belle histoire d'amour avec, en toile de fond, une fresque de Cordoue du 12e siècle. -- Services Documentaires Multimédia\n\nAssuntos importados: Espagne","pages":136,"place":"Paris","title":"Sarah de Cordoue","source":{"leader":"01984nam0 22002651i 450 ","dialect":"unimarc","itemTag":"995","fieldsCount":18},"language":"fr","originId":"5","publisher":"Syros jeunesse","collection":"Les |uns, les autres","externalIds":[{"label":"PMB 8.1 (fixtures)","value":"5"}],"contributors":[{"name":"Causse, Rolande","role":"autor","nature":"person","primary":true,"roleCode":"070"}],"materialType":"livro","responsibility":"Causse, Rolande"},{"isbn":"2-207-24700-7","work":{"title":"Le mille-pattes"},"year":"1998","items":[{"code":"33700003550072","note":"Reliure bibliographique très abîmée. Comparer coût réparation et rééquipement.","callNumber":"RX RIO","visibility":"public","circulationPolicy":"ambos"}],"notes":"Le titre crypté désigne les onze joueurs de l'équipe de France de football impliqués en ce récit dans une intrigue \"alternative\" par rapport à l'événement de 1998. -- Services Documentaires Multimédia\n\nPalavras-chave importadas: bleus; champions du monde; 1998; policier; ballon rond\n\nAssuntos importados: Littérature française; Football","pages":233,"place":"Paris","title":"Le mille-pattes","source":{"leader":"01854nam0 22002531i 450 ","dialect":"unimarc","itemTag":"995","fieldsCount":17},"language":"fr","originId":"6","subtitle":"roman","publisher":"Denoël","externalIds":[{"label":"PMB 8.1 (fixtures)","value":"6"}],"contributors":[{"name":"Riou, Jean-Michel","role":"autor","nature":"person","primary":true,"roleCode":"070"}],"materialType":"livro","responsibility":"Riou, Jean-Michel"},{"cdd":"810","isbn":"2-08-164155-0","work":{"title":"Le puits"},"year":"1997","items":[{"code":"33700004389030","callNumber":"JRK TAY","visibility":"public","circulationPolicy":"ambos"},{"code":"33700004389026","callNumber":"JRK TAY","visibility":"public","circulationPolicy":"ambos"}],"notes":"La sécheresse a tari tous les puits de la région. Tous sauf celui des Logan, famille de fermiers noirs aisée. Les Logan partagent cette eau précieuse de grand cœur, avec tous. Mais en 1910, dans le Sud américain, les rancœurs contre les Noirs sont tenaces... Tout au long de l'été, la tension monte, aussi accablante que la chaleur.\n\nPalavras-chave importadas: coton; policier\n\nAssuntos importados: Littérature américaine","pages":110,"place":"[Paris]","title":"Le puits","source":{"leader":"02452nam0 22002891i 450 ","dialect":"unimarc","itemTag":"995","fieldsCount":18},"language":"fr","originId":"7","publisher":"Flammarion","externalIds":[{"label":"PMB 8.1 (fixtures)","value":"7"}],"contributors":[{"name":"Taylor, Mildred D.","role":"autor","nature":"person","primary":true,"roleCode":"070"},{"name":"Vassallo-Villaneau, Rose-Marie","role":"outro","nature":"person","primary":false}],"materialType":"livro","responsibility":"Taylor, Mildred D.; Vassallo-Villaneau, Rose-Marie"},{"cdd":"760","isbn":"2-7234-1542-2","work":{"title":"Ghetto 9"},"year":"1993","items":[{"code":"33700003669468","callNumber":"BD ADA","visibility":"public","circulationPolicy":"ambos"}],"notes":"Dans une Afrique futuriste, un consortium exploite à outrance les ressources du continent. Et quand Dayak découvre que l'homme qui dirige cet empire technologique n'est autre que son propre frère, la lutte prend une dimension fascinante. Dayak possède l'énergie et la force des meilleures sagas de S.F. et confirme le talent visionnaire du dessin d'Adamov, qui signe là son premier scénario.\n\nAssuntos importados: Science-fiction","pages":47,"place":"Grenoble","title":"Ghetto 9","source":{"leader":"01942nam0 22002651i 450 ","dialect":"unimarc","itemTag":"995","fieldsCount":18},"language":"fr","originId":"8","publisher":"Glénat","collection":"Dayak.","externalIds":[{"label":"PMB 8.1 (fixtures)","value":"8"}],"contributors":[{"name":"Adamov, Philippe","role":"autor","nature":"person","primary":true,"roleCode":"070"}],"materialType":"livro","responsibility":"Adamov, Philippe"},{"cdd":"760","isbn":"2-7234-2083-3","work":{"title":"Zaks"},"year":"1997","items":[{"code":"33700003669484","callNumber":"BD ADA","visibility":"public","circulationPolicy":"ambos"}],"notes":"Une fois la ville-mère détruite, implosée, Dayak a réussi à échapper aux intercepteurs.En compagnie de son fidèle P'tit Caille, le voilà au coeur du désert, prêt à se fondre dans cet univers inhospitalier, mais toujours suivi, à quelque distance, par son frère Simon, plus que jamais décidé à le rattraper. Or le Grand Désert est aussi le domaine des Zaks, les hommes-masques aux yeux sanguins. N'est-ce qu'un peuple de légende, où sont-ils vraiment là, cachés dans un dédale de galeries souterraines labyrinthiques ?Dayak ne tardera pas à être fixé . Bientôt résonneront les tambours des traditions humaines les plus anciennes, et les ombres démesurées des silhouettes primitives viendront s'allonger auprès de lui.Grâce à leur intervention, Dayak parviendra à triompher définitivement de son frère, si tant est que la mort, pour les gens de son espèce, soit vraiment une fin...Alors, qui sont au juste ces Zaks qui s'expriment en ces lieux désertiques ?Et si Dayak, d'une certaine façon, finissait par devenir l'un des leurs ?...\n\nAssuntos importados: Science-fiction","pages":47,"place":"Grenoble","title":"Zaks","source":{"leader":"02575nam0 22002651i 450 ","dialect":"unimarc","itemTag":"995","fieldsCount":18},"language":"fr","originId":"9","publisher":"Glénat","collection":"Dayak.","externalIds":[{"label":"PMB 8.1 (fixtures)","value":"9"}],"contributors":[{"name":"Adamov, Philippe","role":"autor","nature":"person","primary":true,"roleCode":"070"}],"materialType":"livro","responsibility":"Adamov, Philippe"},{"cdd":"760","isbn":"2-7234-1727-1","work":{"title":"La chambre verte"},"year":"1994","items":[{"code":"33700003669485","callNumber":"BD ADA","visibility":"public","circulationPolicy":"ambos"}],"notes":"La nouvelle Addis Abeba est née !Fini le ghetto, sa misère et sa crasse... Simon Colbius, leader de la C.P.M., a fait surgir une mégalopole où les techniques les plus sophistiquées côtoient les traditions les plus anciennes.Un monde où P'tit Caille est devenu le valet de chambre du nouveau despote et Cori une courtisane que le nouveau comportement de Dayak trouble à peine.Car Dayak sait maintenant qu'il est le frère de Simon, il a retrouvé dans de lointains souvenirs la vision fugace de cette Chambre verte où, enfants, ils percevaient les formidables changements que leur père orchestrait.Devenu le clone de Simon, Dayak parviendra-t-il à briser les chaînes qui le relient à ce frère qui se rêve maître de l'Afrique et empereur d'un nouvel âge ?\n\nAssuntos importados: Science-fiction","pages":47,"place":"Grenoble","title":"La chambre verte","source":{"leader":"02303nam0 22002651i 450 ","dialect":"unimarc","itemTag":"995","fieldsCount":18},"language":"fr","originId":"10","publisher":"Glénat","collection":"Dayak.","externalIds":[{"label":"PMB 8.1 (fixtures)","value":"10"}],"contributors":[{"name":"Adamov, Philippe","role":"autor","nature":"person","primary":true,"roleCode":"070"}],"materialType":"livro","responsibility":"Adamov, Philippe"},{"cdd":"760","isbn":"2-7234-2062-0","work":{"title":"Le chirurgien hollandais"},"year":"1996","items":[{"code":"33700004243164","callNumber":"JBD LAM","visibility":"public","circulationPolicy":"ambos"}],"notes":"Ile de Java, région de Semarang en 1897. Un décor exotique pour une aventure riche en rebondissements. Ironie et drame se conjugent pour ce premier tome d'une nouvelle série qui confirme le talent de Christian Lamquet.\nUn chirurgien hollandais a découvert un crâne qu'il cherche à faire authentifier comme l'un des chaînons manquant de l'histoire de l'homme. Autour de lui, des personnages haut en couleurs : savants baroques, veuve éplorée, la guenon Lucy, un journaliste zélé, une femme qui ne rêve que de maternité. Et enfin : Pete, le crâne, lui-même personnage central de ce récit utilisant habilement théosophie, un mélange d'occultisme et de spiritisme, et anthropologie.\nParce qu'il est convaincu d'avoir mis à jour des fossiles du fameux \"chaînon manquant\", Jacob Boos, un chirurgien hollandais en garnison à Semarang, est bien décidé à remuer ciel, terre, océan et bonne conscience pour prouver au monde la réalité de sa découverte...\n\" Pete \" comme il le surnomme affectueusement, était-il vraiment ce petit \"homme-singe debout\" parcourant la savane voici deux millions d'années ?\nPour l'heure, ce qu'il a laissé de lui sommeille dans une valise : quelques bouts de vertèbres, un crâne, un morceau de mâchoire. Si Jacob y investit tous ses espoirs, d'autres vont y engluer les précieuses reliques dans les délires de leurs utopies, de leurs passions ou de leur bêtises...\n Et puis tous ces malheurs qui se succèdent...\nPete, du fond de sa valise, porterait-il la poisse ?\n\nPalavras-chave importadas: bande dessinée\n\nAssuntos importados: Bande dessinée","pages":47,"place":"Grenoble","title":"Le chirurgien hollandais","source":{"leader":"03043nam0 22002531i 450 ","dialect":"unimarc","itemTag":"995","fieldsCount":17},"language":"fr","originId":"11","publisher":"Glénat","externalIds":[{"label":"PMB 8.1 (fixtures)","value":"11"}],"contributors":[{"name":"Lamquet, Chris","role":"autor","nature":"person","primary":true,"roleCode":"070"}],"materialType":"livro","responsibility":"Lamquet, Chris"},{"isbn":"2-86967-551-8","work":{"title":"La Chrysalide Diaprée"},"year":"1997","items":[{"code":"33700003868672","callNumber":"JBD GAL","visibility":"public","circulationPolicy":"ambos"}],"notes":"Pour sauver son grand-père qui se meurt, Benjamin doit ramener le Mangecoeur, un papillon funeste, avant l'aube. Poursuivi par des clowns cruels dans une fête foraine où seuls les adultes sont admis, il rencontre Rififi, seul allié dans sa fuite. Mais cet ami et son compagnon Pantagas utilisent Benjamin à des fins peu louables... Le rêve et la magie règnent en maîtres dans ce conte merveilleux peuplé de clowns dangereusement malicieux. Le trait brillant de Jean-Baptiste Andréae s'associe au scénario plus qu'efficace de Mathieu Gallié.\n\nPalavras-chave importadas: bande dessinée\n\nAssuntos importados: Bande dessinée","pages":48,"place":"Issy-les-Moulineaux","title":"La Chrysalide Diaprée","source":{"leader":"02320nam0 22002651i 450 ","dialect":"unimarc","itemTag":"995","fieldsCount":18},"language":"fr","originId":"12","publisher":"Vents d'Ouest","externalIds":[{"label":"PMB 8.1 (fixtures)","value":"12"}],"contributors":[{"name":"Gallié, Mathieu","role":"autor","nature":"person","primary":true,"roleCode":"070"},{"name":"Andréaé, Jean-Baptiste","role":"ilustrador","nature":"person","primary":false,"roleCode":"440"}],"materialType":"livro","responsibility":"Gallié, Mathieu; Andréaé, Jean-Baptiste"},{"cdd":"760","isbn":"2-8001-2334-6","work":{"title":"Monsieur Je-sais-tout"},"year":"1998","items":[{"code":"33700004243347","callNumber":"EBD GEE","visibility":"public","circulationPolicy":"ambos"}],"notes":"Assuntos importados: Bande dessinée","pages":48,"place":"[Paris]","title":"Monsieur Je-sais-tout","source":{"leader":"01407nam0 22002291i 450 ","dialect":"unimarc","itemTag":"995","fieldsCount":15},"language":"fr","originId":"13","publisher":"Dupuis","externalIds":[{"label":"PMB 8.1 (fixtures)","value":"13"}],"contributors":[{"name":"Geerts, André","role":"autor","nature":"person","primary":true,"roleCode":"070"}],"materialType":"livro","responsibility":"Geerts, André"},{"cdd":"800","isbn":"2-226-09017-7","work":{"title":"Paroles de bonheur"},"year":"1997","items":[{"code":"33700003453202","callNumber":"J 808 PAR","visibility":"public","circulationPolicy":"ambos"}],"notes":"Bibliogr., 2 p.\n\nCollection anthologique de textes de tous les temps et de tous les pays sur un thème donné. Présentation originale où les écrits sont enclavés dans les illustrations. -- Services Documentaires Multimédia\n\nAssuntos importados: Psychologie - Psychanalyse","place":"Paris","title":"Paroles de bonheur","source":{"leader":"01781nam0 22002891i 450 ","dialect":"unimarc","itemTag":"995","fieldsCount":20},"language":"fr","originId":"14","publisher":"A. Michel","collection":"Paroles","externalIds":[{"label":"PMB 8.1 (fixtures)","value":"14"}],"contributors":[{"name":"Got, Yves","role":"outro","nature":"person","primary":false},{"name":"Robin, Christian","role":"organizador","nature":"person","primary":false,"roleCode":"340"}],"materialType":"livro","responsibility":"Got, Yves; Robin, Christian"},{"cdd":"580","isbn":"2-7324-2351-3","work":{"title":"La métamorphose des fleurs"},"year":"1997","items":[{"code":"33700004118010","callNumber":"582 NUR","visibility":"public","circulationPolicy":"ambos"}],"notes":"Avec Microcosmos, des milliers de lecteurs se sont émerveillés devant les prodiges insoupçonnés d'un petit carré d'herbes folles. Dans la Métamorphose des Fleurs, Claude Nuridsany et Marie Pérennou sillonnent prairies et jardins et invitent nos yeux inattentifs à se poser sur un bouton gorgé de sève, un pétale qui s'entrouvre ou la chute d'une corolle. Autant de moments phares de la vie flamboyante d'une fleur, architecture de rêve construite et défaite en quelques jours. Transfigurées par la magie de la macrophotographie, une vingtaine d'espèces florales naissent, vivent et meurent sous nos yeux. Marie Pérennou et Claude Nuridsany ont inventé, pour notre plus grand plaisir, un nouveau regard sur la nature, à mi-chemin entre la biologie et la poésie.\n\nPalavras-chave importadas: fleur; pistil; étamine; macrophotographie\n\nAssuntos importados: Fleurs","pages":143,"place":"Paris","title":"La métamorphose des fleurs","source":{"leader":"02348nam0 22002651i 450 ","dialect":"unimarc","itemTag":"995","fieldsCount":18},"language":"fr","originId":"15","publisher":"La Martinière","externalIds":[{"label":"PMB 8.1 (fixtures)","value":"15"}],"contributors":[{"name":"Nuridsany, Claude","role":"autor","nature":"person","primary":true,"roleCode":"070"},{"name":"Pérennou, Marie","role":"outro","nature":"person","primary":false,"roleCode":"007"}],"materialType":"livro","responsibility":"Nuridsany, Claude; Pérennou, Marie"},{"cdd":"960","isbn":"2-7384-5292-2","work":{"title":"Rwanda"},"year":"1997","items":[{"code":"33700003286792","callNumber":"967 OVE","visibility":"public","circulationPolicy":"ambos"}],"notes":"En appendice, choix de documents\n\nPalavras-chave importadas: afrique franchophone; rwanda; histoire de la colonisation\n\nAssuntos importados: Rwanda","pages":271,"place":"Paris","title":"Rwanda","source":{"leader":"01516nam0 22002531i 450 ","dialect":"unimarc","itemTag":"995","fieldsCount":17},"language":"fr","originId":"16","subtitle":"un peuple avec une histoire","publisher":"l'Harmattan","externalIds":[{"label":"PMB 8.1 (fixtures)","value":"16"}],"contributors":[{"name":"Overdulve, Cornelis Marinus","role":"autor","nature":"person","primary":true,"roleCode":"070"}],"materialType":"livro","responsibility":"Overdulve, Cornelis Marinus"},{"cdd":"910","isbn":"2-06-100392-3","work":{"title":"Carte routière : Ardèche - Haute-Loire, N° 11331"},"year":"2002","items":[{"code":"3370000451291","callNumber":"910 MIC","visibility":"public","circulationPolicy":"ambos"}],"notes":"Présentation de l'éditeur\nLa nouvelle génération des cartes routières Michelin ! Toutes les informations pour découvrir, sur une seule carte, un, deux ou trois départements de France et se repérer facilement en voiture.\n\nDe nombreuses nouveautés ont été intégrées à la carte « LOCAL » :\n- une carte plus lisible grâce à une échelle agrandie : 1/150 000e ou 1/175 000e\n- un index complet des localités pour accéder rapidement à l'information\n- des plans de ville pour circuler dans les grandes agglomérations\n- une légende en image pour bien comprendre les symboles de la carte\n- une carte des terroirs\nUne nouvelle collection de cartes centrées sur le \"LOCAL\" pour vivre la route autrement !\npixel\n\nPalavras-chave importadas: bas-vivarais; boutières; brisadois; cévennes; haut-vivarais; margeriche; velay\n\nAssuntos importados: Pays de la Loire","place":"Paris","title":"Carte routière : Ardèche - Haute-Loire, N° 11331","source":{"leader":"02388nem0 22002651i 450 ","dialect":"unimarc","itemTag":"995","fieldsCount":18},"language":"fr","originId":"17","subtitle":"Carte routière et touristique","publisher":"Michelin","externalIds":[{"label":"PMB 8.1 (fixtures)","value":"17"}],"contributors":[{"name":"Editions Michelin","role":"outro","nature":"collective","primary":true,"roleCode":"650"}],"materialType":"livro","responsibility":"Editions Michelin"},{"cdd":"910","work":{"title":"Chili"},"year":"2002","items":[{"code":"3370000451