lse,"source_record_id":"10","titulo_periodico":null,"cover_object_path":null,"holder_library_id":null,"published_book_id":null,"source_record_url":null,"audio_participants":null,"catalog_partner_id":null,"digital_native_url":null,"audiovisual_support":null,"circulation_default":"emprestavel","relatorio_recipient":null,"audio_recording_type":null,"audiovisual_director":null,"audiovisual_duration":null,"audiovisual_language":null,"digital_native_usage":null,"mutualization_status":null,"audiovisual_subtitles":null,"digital_native_access":null,"dossier_organizations":null,"audiovisual_access_note":null,"audiovisual_participants":null,"digital_native_file_note":null,"relatorio_internal_notes":null,"initial_copies_library_id":null,"digital_native_restriction":null},"responsabilites":[{"name":"Adamov, Philippe","role":"autor","nature":"person","position":1,"author_id":null,"role_code":"070","is_primary":true}]},{"row_no":11,"brouillon":{"ano":"1996","cdd":"760","isbn":"2-7234-2062-0","issn":null,"autor":"Lamquet, Chris","notas":"Ile de Java, région de Semarang en 1897. Un décor exotique pour une aventure riche en rebondissements. Ironie et drame se conjugent pour ce premier tome d'une nouvelle série qui confirme le talent de Christian Lamquet.\nUn chirurgien hollandais a découvert un crâne qu'il cherche à faire authentifier comme l'un des chaînons manquant de l'histoire de l'homme. Autour de lui, des personnages haut en couleurs : savants baroques, veuve éplorée, la guenon Lucy, un journaliste zélé, une femme qui ne rêve que de maternité. Et enfin : Pete, le crâne, lui-même personnage central de ce récit utilisant habilement théosophie, un mélange d'occultisme et de spiritisme, et anthropologie.\nParce qu'il est convaincu d'avoir mis à jour des fossiles du fameux \"chaînon manquant\", Jacob Boos, un chirurgien hollandais en garnison à Semarang, est bien décidé à remuer ciel, terre, océan et bonne conscience pour prouver au monde la réalité de sa découverte...\n\" Pete \" comme il le surnomme affectueusement, était-il vraiment ce petit \"homme-singe debout\" parcourant la savane voici deux millions d'années ?\nPour l'heure, ce qu'il a laissé de lui sommeille dans une valise : quelques bouts de vertèbres, un crâne, un morceau de mâchoire. Si Jacob y investit tous ses espoirs, d'autres vont y engluer les précieuses reliques dans les délires de leurs utopies, de leurs passions ou de leur bêtises...\n Et puis tous ces malheurs qui se succèdent...\nPete, du fond de sa valise, porterait-il la poisse ?\n\nPalavras-chave importadas: bande dessinée\n\nAssuntos importados: Bande dessinée","action":"create","edicao":null,"idioma":"fr","numero":null,"status":"draft","titulo":"Le chirurgien hollandais","volume":null,"colecao":null,"editora":"Glénat","paginas":47,"work_id":null,"loanable":true,"subjects":null,"fasciculo":null,"gravadora":null,"marc_json":{"ingest":{"row_no":11,"authors":["Lamquet, Chris"],"subjects":["Bande dessinée"],"partner_name":"PMB 8.1 (fixtures)","editorial_note":null,"detected_format":"marc_iso2709","relation_status":"mapeada","original_filename":"pmb.iso","editorial_decision":"accept_new","derived_collection_hint":null,"derived_local_classification_hint":null},"normalise_md5":"d0c219da38087f553799aa5ab685bf4b","raw_payload_md5":"ff8e98eb74589e98b61aab9e124ac781","anarbib_provenance":{"partner_source":"other_partner","source_record_id":"11"}},"serial_id":null,"subtitulo":null,"created_by":"11111111-1111-1111-1111-111111111111","updated_by":"11111111-1111-1111-1111-111111111111","data_edicao":null,"emitter_org":null,"recto_verso":null,"zine_format":null,"artigo_issue":null,"artigo_pages":null,"audio_format":null,"cover_source":null,"source_label":"pmb.iso","tese_advisor":null,"artigo_source":null,"artigo_volume":null,"audio_support":null,"cover_license":null,"distribuidora":null,"dossier_scope":null,"import_format":null,"import_method":null,"owner_library":"BLMF (base de test)","periodicidade":null,"relatorio_org":null,"tipo