é dans sa fuite. Mais cet ami et son compagnon Pantagas utilisent Benjamin à des fins peu louables... Le rêve et la magie règnent en maîtres dans ce conte merveilleux peuplé de clowns dangereusement malicieux. Le trait brillant de Jean-Baptiste Andréae s'associe au scénario plus qu'efficace de Mathieu Gallié.\n\nPalavras-chave importadas: bande dessinée\n\nAssuntos importados: Bande dessinée","action":"create","edicao":null,"idioma":"fr","numero":null,"status":"draft","titulo":"La Chrysalide Diaprée","volume":null,"colecao":null,"editora":"Vents d'Ouest","paginas":48,"work_id":null,"loanable":true,"subjects":null,"fasciculo":null,"gravadora":null,"marc_json":{"ingest":{"row_no":12,"authors":["Gallié, Mathieu","Andréaé, Jean-Baptiste"],"subjects":["Bande dessinée"],"partner_name":"PMB 8.1 (fixtures)","editorial_note":null,"detected_format":"marc_iso2709","relation_status":"mapeada","original_filename":"pmb.iso","editorial_decision":"accept_new","derived_collection_hint":null,"derived_local_classification_hint":null},"normalise_md5":"8205de56431faa5d2423e9aadf0e3e6c","raw_payload_md5":"cb5b637416d66ade0e4ac2106dd73686","anarbib_provenance":{"partner_source":"other_partner","source_record_id":"12"}},"serial_id":null,"subtitulo":null,"created_by":"11111111-1111-1111-1111-111111111111","updated_by":"11111111-1111-1111-1111-111111111111","data_edicao":null,"emitter_org":null,"recto_verso":null,"zine_format":null,"artigo_issue":null,"artigo_pages":null,"audio_format":null,"cover_source":null,"source_label":"pmb.iso","tese_advisor":null,"artigo_source":null,"artigo_volume":null,"audio_support":null,"cover_license":null,"distribuidora":null,"dossier_scope":null,"import_format":null,"import_method":null,"owner_library":"BLMF (base de test)","periodicidade":null,"relatorio_org":null,"tipo_material":"livro","audio_duration":null,"audio_language":null,"dossier_period":null,"holder_library":null,"initial_copies":1,"partner_source":"other_partner","physical_state":null,"tract_camp