_id":null,"digital_native_restriction":null},"responsabilites":[{"name":"Got, Yves","role":"outro","nature":"person","position":1,"author_id":null,"role_code":null,"is_primary":false},{"name":"Robin, Christian","role":"organizador","nature":"person","position":2,"author_id":null,"role_code":"340","is_primary":false}]},{"row_no":15,"brouillon":{"ano":"1997","cdd":"580","isbn":"2-7324-2351-3","issn":null,"autor":"Nuridsany, Claude; Pérennou, Marie","notas":"Avec Microcosmos, des milliers de lecteurs se sont émerveillés devant les prodiges insoupçonnés d'un petit carré d'herbes folles. Dans la Métamorphose des Fleurs, Claude Nuridsany et Marie Pérennou sillonnent prairies et jardins et invitent nos yeux inattentifs à se poser sur un bouton gorgé de sève, un pétale qui s'entrouvre ou la chute d'une corolle. Autant de moments phares de la vie flamboyante d'une fleur, architecture de rêve construite et défaite en quelques jours. Transfigurées par la magie de la macrophotographie, une vingtaine d'espèces florales naissent, vivent et meurent sous nos yeux. Marie Pérennou et Claude Nuridsany ont inventé, pour notre plus grand plaisir, un nouveau regard sur la nature, à mi-chemin entre la biologie et la poésie.\n\nPalavras-chave importadas: fleur; pistil; étamine; macrophotographie\n\nAssuntos importados: Fleurs","action":"create","edicao":null,"idioma":"fr","numero":null,"status":"draft","titulo":"La métamorphose des fleurs","volume":null,"colecao":null,"editora":"La Martinière","paginas":143,"work_id":null,"loanable":true,"subjects":null,"fasciculo":null,"gravadora":null,"marc_json":{"ingest":{"row_no":15,"authors":["Nuridsany, Claude","Pérennou, Marie"],"subjects":["Fleurs"],"partner_name":"PMB 8.1 (fixtures)","editorial_note":null,"detected_format":"marc_iso2709","relation_status":"mapeada","original_filename":"pmb.iso","editorial_decision":"accept_new","derived_collection_hint":null,"derived_local_classification_hint":null},"normalise_md5":"f36eef482472bbf49d2bdda30df5f3