ichelin ! Toutes les informations pour découvrir, sur une seule carte, un, deux ou trois départements de France et se repérer facilement en voiture.\n\nDe nombreuses nouveautés ont été intégrées à la carte « LOCAL » :\n- une carte plus lisible grâce à une échelle agrandie : 1/150 000e ou 1/175 000e\n- un index complet des localités pour accéder rapidement à l'information\n- des plans de ville pour circuler dans les grandes agglomérations\n- une légende en image pour bien comprendre les symboles de la carte\n- une carte des terroirs\nUne nouvelle collection de cartes centrées sur le \"LOCAL\" pour vivre la route autrement !\npixel\n\nPalavras-chave importadas: bas-vivarais; boutières; brisadois; cévennes; haut-vivarais; margeriche; velay\n\nAssuntos importados: Pays de la Loire","action":"create","edicao":null,"idioma":"fr","numero":null,"status":"draft","titulo":"Carte routière : Ardèche - Haute-Loire, N° 11331","volume":null,"colecao":null,"editora":"Michelin","paginas":null,"work_id":null,"loanable":true,"subjects":null,"fasciculo":null,"gravadora":null,"marc_json":{"ingest":{"row_no":17,"authors":["Editions Michelin"],"subjects":["Pays de la Loire"],"partner_name":"PMB 8.1 (fixtures)","editorial_note":null,"detected_format":"marc_iso2709","relation_status":"mapeada","original_filename":"pmb.iso","editorial_decision":"accept_new","derived_collection_hint":null,"derived_local_classification_hint":null},"normalise_md5":"c65cebd3ce804a275a37f4efb3a635e6","raw_payload_md5":"6f11541363f3f010925cc872b958314e","anarbib_provenance":{"partner_source":"other_partner","source_record_id":"17"}},"serial_id":null,"subtitulo":"Carte routière et touristique","created_by":"11111111-1111-1111-1111-111111111111","updated_by":"11111111-1111-1111-1111-111111111111","data_edicao":null,"emitter_org":null,"recto_verso":null,"zine_format":null,"artigo_issue":null,"artigo_pages":null,"audio_format":null,"cover_source":null,"source_label":"pmb.iso","tese_advisor":null,"artigo_source":null,"