}]}},{"row_no":11,"external_key":"11","item_type":"am","title":"Le chirurgien hollandais","subtitle":null,"responsibility_statement":"Lamquet, Chris","authors":["Lamquet, Chris"],"publisher":"Glénat","place_of_publication":"Grenoble","publication_year":"1996","edition_statement":null,"language":"fre","isbn":"2-7234-2062-0","issn":null,"subjects":["Bande dessinée"],"raw_payload":{"leader":"03043nam0 22002531i 450 ","fields":[{"tag":"001","value":"11"},{"tag":"100","ind1":" ","ind2":" ","subfields":[{"code":"a","value":"20050101u        u  u0frey50  "}]},{"tag":"009","value":"  \u001fa1996-01-01\u001fc2005-01-01 00:00:00\u001fu2010-09-21 13:55:07"},{"tag":"200","ind1":"1","ind2":" ","subfields":[{"code":"a","value":"Le chirurgien hollandais"}]},{"tag":"010","ind1":" ","ind2":" ","subfields":[{"code":"a","value":"2-7234-2062-0"}]},{"tag":"101","ind1":"0","ind2":" ","subfields":[{"code":"a","value":"fre"}]},{"tag":"215","ind1":" ","ind2":" ","subfields":[{"code":"a","value":"47 p."},{"code":"c","value":"ill. en coul., couv. ill. en coul."},{"code":"d","value":"32 cm"}]},{"tag":"330","ind1":" ","ind2":" ","subfields":[{"code":"a","value":"Ile de Java, région de Semarang en 1897. Un décor exotique pour une aventure riche en rebondissements. Ironie et drame se conjugent pour ce premier tome d'une nouvelle série qui confirme le talent de Christian Lamquet.\nUn chirurgien hollandais a découvert un crâne qu'il cherche à faire authentifier comme l'un des chaînons manquant de l'histoire de l'homme. Autour de lui, des personnages haut en couleurs : savants baroques, veuve éplorée, la guenon Lucy, un journaliste zélé, une femme qui ne rêve que de maternité. Et enfin : Pete, le crâne, lui-même personnage central de ce récit utilisant habilement théosophie, un mélange d'occultisme et de spiritisme, et anthropologie.\nParce qu'il est convaincu d'avoir mis à jour des fossiles du fameux \"chaînon manquant\", Jacob Boos, un chirurgien hollandais en garnison à Semarang, est bien décidé à remuer ciel, terre, océan et bonne conscience pour prouver au monde la réalité de sa découverte...\n\" Pete \" comme il le surnomme affectueusement, était-il vraiment ce petit \"homme-singe debout\" parcourant la savane voici deux millions d'années ?\nPour l'heure, ce qu'il a laissé de lui sommeille dans une valise : quelques bouts de vertèbres, un crâne, un morceau de mâchoire. Si Jacob y investit tous ses espoirs, d'autres vont y engluer les précieuses reliques dans les délires de leurs utopies, de leurs passions ou de leur bêtises...\n Et puis tous ces malheurs qui se succèdent...\nPete, du fond de sa valise, porterait-il la poisse ?  "}]},{"tag":"319","ind1":" ","ind2":" ","subfields":[{"code":"a","value":"Aucun droit spécifique"}]},{"tag":"700","ind1":" ","ind2":"1","subfields":[{"code":"a","value":"Lamquet"},{"code":"b","value":"Chris"},{"code":"4","value":"070"},{"code":"f","value":"1954-...."},{"code":"9","value":"id:10"}]},{"tag":"210","ind1":" ","ind2":" ","subfields":[{"code":"a","value":"Grenoble"},{"code":"b","value":"Grenoble"},{"code":"c","value":"Glénat"},{"code":"d","value":"1996"},{"code":"h","value":"1996-01-01"},{"code":"9","value":"id:7"}]},{"tag":"214","ind1":" ","ind2":" ","subfields":[{"code":"a","value":"Grenoble"},{"code":"b","value":"Grenoble"},{"code":"c","value":"Glénat"},{"code":"d","value":"1996"},{"code":"h","value":"1996-01-01"},{"code":"9","value":"id:7"}]},{"tag":"676","ind1":" ","ind2":" ","subfields":[{"code":"a","value":"760"},{"code":"l","value":"Arts graphiques - graphisme"},{"code":"9","value":"id:77"}]},{"tag":"896","ind1":" ","ind2":" ","subfields":[{"code":"a","value":"http://127.0.0.1:8088/pmb/opac_css/thumbnail.php?type=1&id=11&database=bibli"}]},{"tag":"995","ind1":" ","ind2":" ","subfields":[{"code":"a","value":"Fonds propre"},{"code":"c","value":"Fonds propre"},{"code":"f","value":"33700004243164"},{"code":"k","value":"JBD LAM"},{"code":"r","value":"uu"},{"code":"q","value":"u"}]},{"tag":"996","ind1":" ","ind2":" ",